using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Notes storage (shared across tool invocations) ---
var notes = new List<string>();

// --- Tool definitions ---
AIFunction webSearchTool = AIFunctionFactory.Create(
    async (string query) =>
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍 Searching the web for: \"{query}\"");
        Console.ResetColor();

        try
        {
            using var http = new HttpClient();
            http.DefaultRequestHeaders.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
            var html = await http.GetStringAsync(url);

            // Extract text snippets from the lightweight DuckDuckGo page
            var snippets = ExtractSnippets(html, maxSnippets: 6);
            var result = snippets.Count > 0
                ? string.Join("\n\n", snippets)
                : "No results found. Try rephrasing your query.";

            return result;
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    },
    name: "web_search",
    description: "Searches the web using DuckDuckGo and returns text snippets. Use this to find current information about any topic.");

AIFunction saveNoteTool = AIFunctionFactory.Create(
    (string note) =>
    {
        notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note saved ({notes.Count} total)");
        Console.ResetColor();
        return $"Note saved. You now have {notes.Count} note(s).";
    },
    name: "save_note",
    description: "Saves a research note for later use in the summary. Call this to record key findings, facts, or quotes discovered during research.");

AIFunction readNotesTool = AIFunctionFactory.Create(
    () =>
    {
        if (notes.Count == 0)
            return "No notes saved yet.";
        var result = string.Join("\n", notes.Select((n, i) => $"[{i + 1}] {n}"));
        return result;
    },
    name: "read_notes",
    description: "Reads all previously saved research notes. Use this before writing your final summary to review what you've collected.");

// --- Build the chat client with automatic function-calling ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new[] { webSearchTool, saveNoteTool, readNotesTool };

// --- Agent system prompt ---
const string SystemPrompt = """
    You are a research agent. Given a topic, you thoroughly research it by:
    1. Breaking the topic into sub-questions.
    2. Using the web_search tool to find information (make multiple searches).
    3. Using save_note to record each important finding as you go.
    4. After gathering enough information, using read_notes to review everything.
    5. Producing a well-structured summary with key findings.

    Be thorough — make at least 3 different searches to cover the topic from
    multiple angles. Save a note after each productive search.
    """;

// --- Main interaction loop ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬 AI Research Agent           ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or       ║");
Console.WriteLine("║  type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notes.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, SystemPrompt),
        new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary:\n\n{topic}")
    };

    var options = new ChatOptions { Tools = [.. tools] };

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("  Agent is researching… (this may take a moment)");
    Console.ResetColor();

    var response = await chatClient.GetResponseAsync(messages, options);

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.WriteLine("══════════════ Research Summary ══════════════");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.WriteLine("══════════════════════════════════════════════");
    Console.ResetColor();
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// --- Helper: extract text snippets from DuckDuckGo Lite HTML ---
static List<string> ExtractSnippets(string html, int maxSnippets)
{
    var snippets = new List<string>();

    // DuckDuckGo Lite returns results in <td> elements with class "result-snippet"
    var marker = "result-snippet";
    var idx = 0;
    while (snippets.Count < maxSnippets && (idx = html.IndexOf(marker, idx, StringComparison.Ordinal)) >= 0)
    {
        // Find the closing > of this td tag
        var start = html.IndexOf('>', idx);
        if (start < 0) break;
        start++;

        var end = html.IndexOf("</td>", start, StringComparison.OrdinalIgnoreCase);
        if (end < 0) break;

        var snippet = html[start..end];
        // Strip remaining HTML tags
        snippet = System.Text.RegularExpressions.Regex.Replace(snippet, "<[^>]+>", " ");
        snippet = WebUtility.HtmlDecode(snippet).Trim();

        if (snippet.Length > 20)
            snippets.Add(snippet);

        idx = end;
    }

    // Fallback: extract <a> link text if no snippets found
    if (snippets.Count == 0)
    {
        idx = 0;
        var linkMarker = "result-link";
        while (snippets.Count < maxSnippets && (idx = html.IndexOf(linkMarker, idx, StringComparison.Ordinal)) >= 0)
        {
            var start = html.IndexOf('>', idx);
            if (start < 0) break;
            start++;
            var end = html.IndexOf("</a>", start, StringComparison.OrdinalIgnoreCase);
            if (end < 0) break;
            var text = System.Text.RegularExpressions.Regex.Replace(html[start..end], "<[^>]+>", " ");
            text = WebUtility.HtmlDecode(text).Trim();
            if (text.Length > 5)
                snippets.Add(text);
            idx = end;
        }
    }

    return snippets;
}

